//! Offline wire-shape corpus test: every relation page, the catalogue answer and the capabilities answer that the REAL Manager
//! facade code emits (generated by driving the Manager image's own `ManagerReadFacade`/`S1ReadFacade` with a stub source, see
//! `docs/EDGE_IMAGE_BUILD_AND_ROLL_PLAN_20261116.md` 3c) must decode through the Edge's contract decoder and pass the compat
//! authority built from the release file of the set.
//!
//! Skipped unless `EDGE_WIRE_CORPUS` points at a directory laid out as `<old|new>/<set>/<file>.json` with sets `t2_54` and
//! `t1_67`. Optional: `EDGE_WIRE_SETS` (comma list, default both), `EDGE_WIRE_OUT` (write one `key=result` line per case) and
//! `EDGE_WIRE_BASELINE` (such a file from an earlier code version: any case it records as ok must still be ok here).
//! Not covered: mTLS, JWT, HTTP framing and headers, a real database, real row values.

use std::{
    collections::BTreeMap,
    fs,
    path::{Path, PathBuf},
};

use manager_compat_authority::{
    DeploymentEnvironment, ManagerCompatibilityAuthority, ManagerRequestContext, DELEGATED_RESOURCE,
};
use manager_v2_contract::{
    decode_success_for_profile, ManagerPayload, PageLimit, RUNTIME_CONTRACT_REVISION,
};
use serde_json::Value;
use sha2::{Digest as _, Sha256};

const PROFILE: &str = "PAPER_BINANCE_USDM";
const T2_RELEASE: &[u8] = include_bytes!(
    "../../../../../scripts/epg10-08/t1-release/artifacts/t2-live-manager-catalogue-release.json"
);
const T1_RELEASE: &[u8] = include_bytes!(
    "../../../../../scripts/epg10-08/t1-release/artifacts/manager-catalogue-release.json"
);

fn read_body(path: &Path) -> (u16, Vec<u8>) {
    let doc: Value = serde_json::from_slice(
        &fs::read(path).unwrap_or_else(|e| panic!("{}: {e}", path.display())),
    )
    .unwrap();
    (
        u16::try_from(doc["status"].as_u64().unwrap()).unwrap(),
        serde_json::to_vec(&doc["body"]).unwrap(),
    )
}

#[test]
#[allow(clippy::too_many_lines)]
fn every_manager_wire_shape_decodes_through_the_edge_contract_and_authority() {
    let Ok(corpus) = std::env::var("EDGE_WIRE_CORPUS") else {
        eprintln!("EDGE_WIRE_CORPUS not set: wire-shape corpus test skipped");
        return;
    };
    let corpus = PathBuf::from(corpus);
    let wanted: Vec<String> = std::env::var("EDGE_WIRE_SETS")
        .unwrap_or_else(|_| "t2_54,t1_67".to_owned())
        .split(',')
        .map(str::to_owned)
        .collect();
    let mut results: BTreeMap<String, String> = BTreeMap::new();

    for (set, release) in [("t2_54", T2_RELEASE), ("t1_67", T1_RELEASE)] {
        if !wanted.iter().any(|w| w == set) {
            continue;
        }
        let authority = match ManagerCompatibilityAuthority::from_pinned_release(
            release,
            &format!("sha256:{:x}", Sha256::digest(release)),
            DeploymentEnvironment::Paper,
            PROFILE,
        ) {
            Ok(authority) => authority,
            Err(error) => {
                results.insert(format!("{set}|loader"), format!("err:{error}"));
                continue;
            }
        };
        results.insert(format!("{set}|loader"), "ok".to_owned());
        let bound = authority
            .bind(ManagerRequestContext {
                environment: DeploymentEnvironment::Paper,
                profile_id: PROFILE,
                delegated_resource: DELEGATED_RESOURCE,
                owner_contract_revision: RUNTIME_CONTRACT_REVISION,
            })
            .unwrap();
        let manifest: Value = serde_json::from_slice(release).unwrap();
        let relations: Vec<String> = manifest["relations"]
            .as_array()
            .unwrap()
            .iter()
            .map(|name| name.as_str().unwrap().to_owned())
            .collect();

        for generation in ["old", "new"] {
            let dir = corpus.join(generation).join(set);
            let tag = format!("{set}|{generation}");
            // catalogue answer (carries the optional source_identity member on the identity image)
            let (status, body) = read_body(&dir.join("_catalogue.json"));
            assert_eq!(status, 200, "{tag} catalogue status");
            let catalogue =
                match decode_success_for_profile(&bound.catalogue_request(), &body, PROFILE) {
                    Ok(ManagerPayload::Catalogue(envelope)) => {
                        let catalogue = envelope.into_data();
                        let verdict = bound
                            .validate_catalogue(&catalogue)
                            .map_or_else(|e| format!("err:authority {e}"), |()| "ok".to_owned());
                        results.insert(format!("{tag}|_catalogue"), verdict);
                        Some(catalogue)
                    }
                    Ok(_) => {
                        results.insert(format!("{tag}|_catalogue"), "err:wrong payload".to_owned());
                        None
                    }
                    Err(error) => {
                        results.insert(format!("{tag}|_catalogue"), format!("err:{error}"));
                        None
                    }
                };
            let (_, body) = read_body(&dir.join("_capabilities.json"));
            let verdict =
                match decode_success_for_profile(&bound.capabilities_request(), &body, PROFILE) {
                    Ok(ManagerPayload::Capabilities(envelope)) => bound
                        .validate_capabilities(envelope.data())
                        .map_or_else(|e| format!("err:authority {e}"), |()| "ok".to_owned()),
                    Ok(_) => "err:wrong payload".to_owned(),
                    Err(error) => format!("err:{error}"),
                };
            results.insert(format!("{tag}|_capabilities"), verdict);

            let Some(catalogue) = catalogue else { continue };
            for relation in &relations {
                for case in ["page", "empty", "more"] {
                    let key = format!("{tag}|{relation}|{case}");
                    let path = dir.join(format!("{relation}.{case}.json"));
                    let verdict = (|| -> Result<String, String> {
                        let request = bound
                            .relation_page_request(
                                &catalogue,
                                relation,
                                None,
                                PageLimit::new(1).unwrap(),
                            )
                            .map_err(|e| format!("authority {e}"))?;
                        let (status, body) = read_body(&path);
                        if status != 200 {
                            return Err(format!("status {status}"));
                        }
                        match decode_success_for_profile(&request, &body, PROFILE) {
                            Ok(ManagerPayload::RelationRecords(page)) => {
                                let snapshot = page.meta().source_snapshot().is_some();
                                Ok(format!(
                                    "ok items={} cursor={} snapshot={}",
                                    page.data().items().len(),
                                    page.data().next_cursor().is_some(),
                                    if snapshot { "yes" } else { "no" }
                                ))
                            }
                            Ok(_) => Err("wrong payload".to_owned()),
                            Err(error) => Err(format!("decode {error}")),
                        }
                    })();
                    results.insert(key, verdict.unwrap_or_else(|e| format!("err:{e}")));
                }
            }
        }
    }

    if let Ok(out) = std::env::var("EDGE_WIRE_OUT") {
        let lines: Vec<String> = results.iter().map(|(k, v)| format!("{k}={v}")).collect();
        let lines = lines.join("\n") + "\n";
        fs::write(out, lines).unwrap();
    }
    let failures: Vec<String> = results
        .iter()
        .filter(|(_, v)| !v.starts_with("ok"))
        .map(|(k, v)| format!("{k} => {v}"))
        .collect();
    // Differential: whatever an earlier code version decoded must still decode.
    let mut regressions = Vec::new();
    if let Ok(path) = std::env::var("EDGE_WIRE_BASELINE") {
        for line in fs::read_to_string(path).unwrap().lines() {
            let (key, value) = line.split_once('=').unwrap();
            if value.starts_with("ok") && !results.get(key).is_some_and(|v| v.starts_with("ok")) {
                regressions.push(format!("{key}: baseline ok, now {:?}", results.get(key)));
            }
        }
    }
    assert!(
        regressions.is_empty(),
        "accepted by the baseline, rejected here: {regressions:#?}"
    );
    assert!(failures.is_empty(), "wire shapes rejected: {failures:#?}");
    assert!(!results.is_empty());
}
